      key = 0.62;                                                // кадр снаружи экспонирован под тёмный металл: камню хватает трети прежнего света
      // ТЕНЬ от гребней, кромок кратеров и валунов: запечённая карта глубины от Солнца
      if (uShP.w > 0.5) vis = sunVis(vP, N, dot(N, uSun), dist);
